/* Room transport. Simulation and ownership validation run on the server. */
(()=>{'use strict';
 const KEY='iron-veil-room-v1';
 const unbits=(value,w,h)=>{const b=atob(value);return Array.from({length:h},(_,y)=>Array.from({length:w},(_,x)=>!!(b.charCodeAt((y*w+x)>>3)&1<<((y*w+x)&7))));};
 class OnlineMatch{
  constructor(callbacks){this.callbacks=callbacks;this.session=null;this.queue=[];this.nextSeq=1;this.lastResult=0;this.connected=false;this.timer=null;this.generation=0;this.busy=false;this.revision=-1;this.rtt=0;this.backend='';try{this.backend=OnlineMatch.endpoint(localStorage.getItem('iron-veil-server')||'');}catch{}}
  static endpoint(value){if(!value.trim())return '';const u=new URL(value);if(u.username||u.password||u.search||u.hash||!(u.protocol==='https:'||u.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(u.hostname)))throw Error('Use an HTTPS server URL (or localhost for development).');return u.origin;}
  configure(value){if(this.active)throw Error('Leave the current room before changing servers.');this.backend=OnlineMatch.endpoint(value);localStorage.setItem('iron-veil-server',this.backend);}
  get active(){return !!this.session;}
  async request(action,input={}){const started=performance.now(),endpoint=this.session?.backend??this.backend;const response=await fetch(endpoint+'/api/rooms/'+action,{method:'POST',credentials:endpoint?'omit':'same-origin',headers:{'Content-Type':'application/json',...(this.session?.token?{Authorization:'Bearer '+this.session.token}:{})},body:JSON.stringify({...input,...(this.session?{code:this.session.code}: {})}),signal:AbortSignal.timeout(10000)});let result;try{result=await response.json();}catch{throw Error('This address cannot host rooms. Set the multiplayer server URL, or open the hosted game.');}this.rtt=Math.round(performance.now()-started);if(!response.ok){const e=Error(result.error||'Connection failed.');e.status=response.status;throw e;}return result;}
  remember(){try{if(this.session)localStorage.setItem(KEY,JSON.stringify(this.session));else localStorage.removeItem(KEY);}catch{}}
  adopt(result){this.session={code:result.code,token:result.token,seat:result.seat,backend:this.backend};this.queue=[];this.nextSeq=(result.seq||0)+1;this.lastResult=result.seq||0;this.revision=-1;this.connected=true;this.generation++;this.remember();this.accept(result);this.schedule();}
  async create(biome,ai){if(this.active)throw Error('Leave the current room first.');this.adopt(await this.request('create',{biome,ai}));}
  async join(code){if(this.active)throw Error('Leave the current room first.');this.adopt(await this.request('join',{code}));}
  async resume(){let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}if(!saved?.token||!saved?.code)return;this.session={...saved,backend:OnlineMatch.endpoint(saved.backend||'')};this.generation++;try{const result=await this.request('tick');this.nextSeq=result.seq+1;this.lastResult=result.seq;this.connected=true;this.accept(result);this.schedule();}catch(e){if(e.status===401||e.status===404)this.stop();else{this.callbacks.status('Reconnecting to your room…');this.schedule(1500);}}}
  async start(){this.accept(await this.request('start'));}
  async leave(){if(!this.active)return;await this.request('leave');this.stop();this.callbacks.closed();}
  stop(){this.generation++;clearTimeout(this.timer);this.session=null;this.queue=[];this.connected=false;this.revision=-1;this.remember();}
  send(method,args){if(!this.active||!this.connected)return {ok:false,message:'Connection interrupted. Wait for reconnection.'};if(this.queue.length>=64)return {ok:false,message:'Waiting for pending orders. Please try again shortly.'};this.queue.push({seq:this.nextSeq++,method,args});if(!this.busy)this.schedule(0);return {ok:true,message:'Order sent.'};}
  accept(result){if(Number.isFinite(result.revision)&&result.revision<=this.revision)return;if(Number.isFinite(result.revision))this.revision=result.revision;this.connected=true;this.playing=result.status==='playing';this.queue=this.queue.filter(c=>c.seq>result.seq);this.nextSeq=Math.max(this.nextSeq,result.seq+1);for(const answer of result.results||[])if(answer.seq>this.lastResult){this.lastResult=answer.seq;this.callbacks.result(answer);}this.callbacks.room({...result,rtt:this.rtt});if(result.state)this.callbacks.state(result.state,result);if(result.status==='closed'){this.stop();this.callbacks.closed();}}
  schedule(delay=200){clearTimeout(this.timer);if(!this.active||this.busy)return;const generation=this.generation;this.timer=setTimeout(async()=>{this.busy=true;const started=performance.now();try{const result=await this.request('tick',{commands:this.queue.slice(0,8)});if(generation!==this.generation)return;this.accept(result);}catch(e){if(generation!==this.generation)return;this.connected=false;this.callbacks.status(e.status===404?'Room expired. Leave this room and create a new one.':'Connection interrupted — reconnecting…');if(e.status===401||e.status===404){this.stop();this.callbacks.closed();return;}}finally{this.busy=false;}if(generation===this.generation)this.schedule(this.connected?(this.queue.length?0:Math.max(20,(this.playing?200:800)-(performance.now()-started))):1500);},delay);}
  static position(e,now=performance.now()){const p=e._interpolation;if(!p)return {x:e.x,y:e.y};const t=Math.max(0,Math.min(1,(now-p.start)/p.duration));return {x:p.x+(e.x-p.x)*t,y:p.y+(e.y-p.y)*t};}
  static apply(game,state){
   const previous=new Map(game.entities.map(e=>[e.id,e]));const now=performance.now(),gap=game._onlineReceived?now-game._onlineReceived:200;game._onlineReceived=now;game._onlineInterval=Math.max(100,Math.min(1800,(game._onlineInterval||gap)*.4+gap*.6));
   for(const e of state.entities){const old=previous.get(e.id);if(old&&e.kind!=='building'&&e.layer===old.layer&&Math.hypot(e.x-old.x,e.y-old.y)<12){const from=OnlineMatch.position(old,now);e._interpolation={...from,start:now,duration:game._onlineInterval};}if(old&&e.owner===0&&e.kind==='building'&&e.hp<old.hp&&(game._onlineAlert||0)<state.time){game._onlineAlert=state.time+8;game._event(game.getDef(e).name+' is under attack!','danger');}}
   state.teams.forEach((t,i)=>{if(t.eliminated&&!game.teams[i]?.eliminated)game._event(i===0?'Your faction has been eliminated.':'Rival headquarters eliminated. '+state.teams.filter(t=>!t.eliminated).length+' factions remain.',i===0?'danger':'success');});
   Object.assign(game,{entities:state.entities,teams:state.teams,time:state.time,winner:state.winner,preparationDuration:state.preparationDuration,charges:state.charges,effects:state.effects,tunnels:state.tunnels,visible:unbits(state.visible,game.width,game.height),undergroundVisible:unbits(state.undergroundVisible,game.width,game.height),explored:unbits(state.explored,game.width,game.height)});
   game._visibility[0]=game.visible;game._underVisibility[0]=game.undergroundVisible;
   for(const patch of state.terrain){const tile=game.tiles[patch.y]?.[patch.x];if(!tile)continue;if(patch.cleared&&!tile.cleared){tile.cleared=true;tile.type=patch.type;(game._terrainChanges||=[]).push({x:patch.x+.5,y:patch.y+.5});}if(tile.resource&&Number.isFinite(patch.amount))tile.resource.amount=patch.amount;}
   game._pathRevision++;game.paused=true;
  }
 }
 globalThis.OnlineMatch=OnlineMatch;
})();
